// ============ CONFIGURACIÓN DEL CLIENTE (edita solo este bloque) ============
const CONFIG_BASE = {
  tienda: 'Tienda Demo',
  web: 'https://tienda-demo.test',
  fuente: 'demo',                 // 'demo', 'shopify' o 'http'
  carritos_url: '',               // si fuente = 'http': endpoint que devuelve los carritos en JSON
  dominio_shopify: '',            // solo Shopify: tu-tienda.myshopify.com

  // --- la secuencia de avisos (se envía como mucho uno por carrito y ejecución) ---
  pasos: [
    { horas: 1,  asunto: '¿Te ayudamos a terminar tu pedido?', cupon: '' },
    { horas: 24, asunto: 'Tu carrito sigue esperándote',       cupon: '' },
    { horas: 72, asunto: 'Última oportunidad: 10 % en tu carrito', cupon: 'VUELVE10' },
  ],
  horas_limite: 168,              // pasada una semana, el carrito se da por perdido
  minimo_total: 10,               // carritos por debajo de este importe no merecen un email
  max_envios_por_ejecucion: 50,   // freno: evita una avalancha si algo se descuadra

  // --- consentimiento: escribir a quien no lo dio puede costar una multa ---
  solo_con_consentimiento: true,  // no dejes esto en false sin hablarlo con el cliente
  email_bajas: 'bajas@tu-dominio.com',   // dirección de baja que aparece en el pie

  // --- la marca de la TIENDA, que es quien firma el email al comprador ---
  marca_color: '#235b54',
  marca_texto_boton: 'Terminar mi pedido',

  moneda: 'EUR',
  email_from: 'tienda@tu-dominio.com',   // remitente de los avisos al comprador
  email_to: 'cliente@ejemplo.com',       // a quién le llega el RESUMEN (el dueño de la tienda)
  telegram_chat_id: 'TU_CHAT_ID',
};
// ============================================================================

// ---- Panel único de Denoro: los ajustes del cliente llegan en la entrada ----
const __ENTRADA = $input.first().json || {};
const __limpio = (o) => Object.fromEntries(Object.entries(o || {}).filter(([, x]) => x !== '' && x !== null && x !== undefined));
const __mezclar = (b, o) => {
  const r = { ...b };
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) r[k] = { ...b[k], ...__limpio(v) };
    else if (v !== undefined && v !== null) r[k] = v;
  }
  return r;
};
const CONFIG = { ...__mezclar(CONFIG_BASE, __ENTRADA.config), __token: String(__ENTRADA.token || ''), __auto: String(__ENTRADA.auto || ''), __clave: String(__ENTRADA.clave || '') };
if (!CONFIG.__token || !CONFIG.__clave) throw new Error('Esta versión se lanza desde el panel de Denoro (falta el cliente)');
if (!['demo', 'shopify', 'http'].includes(CONFIG.fuente)) {
  throw new Error(`fuente "${CONFIG.fuente}" no válida: usa demo, shopify o http`);
}
if (CONFIG.fuente === 'http' && !/^https?:\/\//i.test(String(CONFIG.carritos_url || ''))) {
  throw new Error('Con fuente = http hace falta un carritos_url que empiece por http:// o https://');
}
if (CONFIG.fuente === 'shopify' && !/\.myshopify\.com$/i.test(String(CONFIG.dominio_shopify || ''))) {
  throw new Error('Con fuente = shopify hace falta dominio_shopify (tu-tienda.myshopify.com)');
}
if (!Array.isArray(CONFIG.pasos) || !CONFIG.pasos.length) throw new Error('Define al menos un paso en pasos');
CONFIG.pasos.forEach((p, i) => {
  if (!(p.horas >= 0)) throw new Error(`El paso ${i + 1} necesita horas (número de horas desde que se abandonó)`);
  if (!String(p.asunto || '').trim()) throw new Error(`El paso ${i + 1} necesita asunto`);
  if (i > 0 && p.horas <= CONFIG.pasos[i - 1].horas) {
    throw new Error(`Los pasos van de menos a más horas: el ${i + 1} (${p.horas} h) no puede ir antes que el ${i} (${CONFIG.pasos[i - 1].horas} h)`);
  }
});
if (CONFIG.horas_limite <= CONFIG.pasos[CONFIG.pasos.length - 1].horas) {
  throw new Error('horas_limite tiene que ser mayor que las horas del último paso');
}
if (!(CONFIG.max_envios_por_ejecucion >= 1 && CONFIG.max_envios_por_ejecucion <= 500)) {
  throw new Error('max_envios_por_ejecucion debe estar entre 1 y 500');
}
const PLACEHOLDER = /ejemplo\.com|tu-dominio|TU_CHAT_ID/i;
for (const k of ['email_to', 'email_from', 'telegram_chat_id', 'email_bajas']) {
  if (PLACEHOLDER.test(String(CONFIG[k] || ''))) {
    throw new Error(`Configura "${k}" en el nodo Configuración (ahora tiene un valor de ejemplo). Déjalo vacío ('') para desactivar ese canal.`);
  }
}
if (!CONFIG.email_from) throw new Error('Falta email_from: sin remitente no se puede escribir a los compradores');
if (!CONFIG.email_bajas) throw new Error('Falta email_bajas: todo email comercial necesita una forma de darse de baja');
if (CONFIG.telegram_chat_id && !/^-?\d+$|^@\w+$/.test(String(CONFIG.telegram_chat_id))) {
  throw new Error('telegram_chat_id debe ser un número (p. ej. 123456789) o @canal');
}
if (!CONFIG.email_to && !CONFIG.telegram_chat_id) throw new Error('Configura al menos un canal para el resumen: email_to o telegram_chat_id');

return [{ json: {
  ...CONFIG,
  enviar_email: Boolean(CONFIG.email_to),
  enviar_telegram: Boolean(CONFIG.telegram_chat_id),
  ahora: new Date().toISOString(),
} }];

// Carritos de ejemplo, colocados en el tiempo para que se vean los tres pasos de la secuencia,
// una recuperación, un carrito sin consentimiento y uno demasiado pequeño.
const cfg = $('Configuración').first().json;
const ahora = new Date(cfg.ahora).getTime();
const hace = (h) => new Date(ahora - h * 3600000).toISOString();
const L = (titulo, unidades, precio) => ({ titulo, unidades, precio });

const C = (id, email, nombre, horas, total, lineas, extra = {}) => ({ json: {
  id, email, nombre,
  total, moneda: cfg.moneda,
  creado_en: hace(horas + 0.5), actualizado_en: hace(horas),
  completado_en: null, acepta_marketing: true,
  url_recuperacion: `${cfg.web}/carrito/${id}`,
  lineas, ...extra,
} });

return [
  C('C-1001', 'ana@ejemplo.test', 'Ana', 2, 78.90, [L('Botella térmica 750 ml', 1, 24.9), L('Mochila de diario 18 L', 1, 54)]),
  C('C-1002', 'bruno@ejemplo.test', 'Bruno', 30, 129.00, [L('Lámpara de pie de lectura', 1, 99), L('Taza de cerámica', 2, 15)]),
  C('C-1003', 'carla@ejemplo.test', 'Carla', 80, 245.00, [L('Mesa auxiliar', 1, 199), L('Vela de soja 220 g', 1, 46)]),
  C('C-1004', 'diego@ejemplo.test', 'Diego', 26, 64.00, [L('Juego de cuchillos', 1, 64)], { completado_en: hace(1) }),
  C('C-1005', 'elena@ejemplo.test', 'Elena', 5, 42.00, [L('Cargador de 65 W', 1, 42)], { acepta_marketing: false }),
  C('C-1006', 'fran@ejemplo.test', 'Fran', 10, 7.90, [L('Cuaderno de bolsillo A6', 1, 7.9)]),
  C('C-1007', '', 'Invitado', 6, 89.00, [L('Mochila de viaje 32 L', 1, 89)]),
  C('C-1008', 'gema@ejemplo.test', 'Gema', 200, 55.00, [L('Esterilla de yoga', 1, 54)]),
];

// Deja los "abandoned checkouts" de Shopify con la forma que usa el resto del workflow.
const cfg = $('Configuración').first().json;
const salida = [];
for (const item of $input.all()) {
  const ch = item.json;
  if (!ch || !ch.id) continue;
  const cliente = ch.customer || {};
  salida.push({ json: {
    id: String(ch.token || ch.id),
    email: (ch.email || cliente.email || '').trim().toLowerCase(),
    nombre: (ch.billing_address?.first_name || cliente.first_name || '').trim(),
    total: parseFloat(ch.total_price || 0),
    moneda: ch.currency || cfg.moneda,
    creado_en: ch.created_at,
    actualizado_en: ch.updated_at || ch.created_at,
    completado_en: ch.completed_at || null,
    // Shopify guarda el consentimiento del comprador en el propio checkout
    acepta_marketing: Boolean(ch.buyer_accepts_marketing ?? cliente.accepts_marketing),
    url_recuperacion: ch.abandoned_checkout_url || '',
    lineas: (ch.line_items || []).map((l) => ({
      titulo: l.title + (l.variant_title ? ` · ${l.variant_title}` : ''),
      unidades: l.quantity, precio: parseFloat(l.price || 0),
    })),
  } });
}
return salida;

// Carritos desde un endpoint propio (un plugin de WooCommerce, un export de la tienda...).
// Se admiten varias formas de nombrar lo mismo para no obligar al cliente a cambiar su endpoint.
const cfg = $('Configuración').first().json;
const primera = $input.first().json;
const lista = Array.isArray(primera) ? primera
  : (primera.carritos || primera.carts || primera.data || primera.items
    || $input.all().map((i) => i.json));
if (!Array.isArray(lista)) throw new Error('El endpoint no devolvió una lista de carritos (ni en carritos, carts, data o items)');

const fecha = (v) => {
  if (!v) return null;
  const n = typeof v === 'number' ? v * (String(v).length <= 10 ? 1000 : 1) : Date.parse(v);
  const d = new Date(n);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const salida = [];
for (const c of lista) {
  if (!c) continue;
  const id = String(c.id ?? c.cart_id ?? c.token ?? c.session_id ?? '').trim();
  if (!id) continue;
  const actualizado = fecha(c.actualizado_en ?? c.updated_at ?? c.last_activity ?? c.creado_en ?? c.created_at);
  if (!actualizado) continue;
  salida.push({ json: {
    id,
    email: String(c.email ?? c.customer_email ?? '').trim().toLowerCase(),
    nombre: String(c.nombre ?? c.first_name ?? c.customer_name ?? '').trim(),
    total: parseFloat(c.total ?? c.cart_total ?? 0) || 0,
    moneda: c.moneda || c.currency || cfg.moneda,
    creado_en: fecha(c.creado_en ?? c.created_at) || actualizado,
    actualizado_en: actualizado,
    completado_en: fecha(c.completado_en ?? c.completed_at ?? c.order_date),
    acepta_marketing: Boolean(c.acepta_marketing ?? c.accepts_marketing ?? c.marketing_consent),
    url_recuperacion: c.url_recuperacion || c.recovery_url || c.checkout_url || '',
    lineas: (c.lineas || c.items || c.line_items || []).map((l) => ({
      titulo: String(l.titulo ?? l.title ?? l.name ?? 'Producto'),
      unidades: Number(l.unidades ?? l.quantity ?? 1),
      precio: parseFloat(l.precio ?? l.price ?? 0) || 0,
    })),
  } });
}
if (!salida.length) throw new Error('Ningún carrito del endpoint traía id y fecha: revisa el formato');
return salida;

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Decide a quién le toca un aviso ahora mismo, y lleva la cuenta de lo recuperado.
// El estado vive en el propio workflow (staticData), así que no hace falta base de datos.
const cfg = $('Configuración').first().json;
const ahora = new Date(cfg.ahora).getTime();
const estado = __estadoCliente();
estado.carritos = estado.carritos || {};
estado.historico = estado.historico || { enviados: 0, recuperados: 0, valor_recuperado: 0 };

const carritos = $input.all().map((i) => i.json).filter((c) => c && c.id);
const envios = [];
const recuperados = [];
const omitidos = { sin_email: 0, sin_consentimiento: 0, importe_bajo: 0, caducados: 0, al_dia: 0 };

for (const c of carritos) {
  const previo = estado.carritos[c.id];
  const enviados = (previo && previo.pasos) || [];

  if (c.completado_en) {
    // Solo se apunta como recuperado si antes le habíamos escrito: si no, es una compra normal.
    if (enviados.length) {
      recuperados.push({ id: c.id, email: c.email, nombre: c.nombre, total: c.total,
        pasos: enviados.length, completado_en: c.completado_en });
      estado.historico.recuperados += 1;
      estado.historico.valor_recuperado = Math.round((estado.historico.valor_recuperado + c.total) * 100) / 100;
    }
    delete estado.carritos[c.id];
    continue;
  }

  const horas = (ahora - Date.parse(c.actualizado_en)) / 3600000;
  if (!(horas >= 0)) continue;
  if (horas > cfg.horas_limite) { omitidos.caducados += 1; delete estado.carritos[c.id]; continue; }
  if (!c.email) { omitidos.sin_email += 1; continue; }
  if (cfg.solo_con_consentimiento && !c.acepta_marketing) { omitidos.sin_consentimiento += 1; continue; }
  if (c.total < cfg.minimo_total) { omitidos.importe_bajo += 1; continue; }

  // Pasos que ya tocaban por tiempo. Si hay varios pendientes se manda el último:
  // a un carrito de hace tres días no se le escribe "¿te ayudamos a terminar?".
  const tocan = cfg.pasos.map((p, i) => (horas >= p.horas ? i + 1 : 0)).filter(Boolean);
  const pendientes = tocan.filter((p) => !enviados.includes(p));
  if (!pendientes.length) { omitidos.al_dia += 1; continue; }
  const paso = pendientes[pendientes.length - 1];

  envios.push({
    ...c,
    paso,
    saltados: pendientes.slice(0, -1),   // los anteriores se dan por pasados, no se enviarán luego
    asunto: cfg.pasos[paso - 1].asunto,
    cupon: cfg.pasos[paso - 1].cupon || '',
    horas_abandonado: Math.round(horas),
  });
}

// Los carritos grandes primero: si hay tope, que se aproveche en lo que más vale.
envios.sort((a, b) => b.total - a.total);
const aEnviar = envios.slice(0, cfg.max_envios_por_ejecucion);

return [{ json: {
  ...cfg,
  hay_envios: aEnviar.length > 0,
  envios: aEnviar,
  en_espera: envios.length - aEnviar.length,
  recuperados,
  omitidos,
  resumen: {
    carritos_vistos: carritos.length,
    avisos: aEnviar.length,
    valor_en_juego: Math.round(aEnviar.reduce((s, e) => s + e.total, 0) * 100) / 100,
    recuperados: recuperados.length,
    valor_recuperado: Math.round(recuperados.reduce((s, e) => s + e.total, 0) * 100) / 100,
    historico: { ...estado.historico },
  },
} }];

// Un item por aviso, con el email que verá el comprador. Lo firma la TIENDA, no Denoro.
const d = $('Decidir a quién escribo').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dinero = (n, m) => `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${m === 'EUR' ? '€' : m}`;
const COLOR = /^#[0-9a-f]{6}$/i.test(String(d.marca_color)) ? d.marca_color : '#235b54';
const TINTA = '#35322c'; const SUAVE = '#6e6a61'; const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef';

const SALUDO = {
  1: (n) => `${n ? `Hola, ${n}` : 'Hola'}: has dejado algo a medias`,
  2: (n) => `${n ? `${n}, tu` : 'Tu'} carrito sigue guardado`,
  3: (n) => `${n ? `${n}, ` : ''}última llamada`,
};
const CUERPO = {
  1: 'Hemos guardado tu carrito por si quieres terminar el pedido. Nada más.',
  2: 'Seguimos guardándote lo que elegiste. Si algo no te encajaba, contéstanos a este correo y lo miramos.',
  3: 'Vamos a liberar el carrito en breve. Si lo quieres, este es el momento.',
};

return d.envios.map((c) => {
  const lineas = c.lineas.map((l) => `<tr>
<td style="padding:8px 0;border-bottom:1px solid ${REGLA};font-size:14px;color:${TINTA}">${esc(l.titulo)}${l.unidades > 1 ? ` <span style="color:${SUAVE}">× ${l.unidades}</span>` : ''}</td>
<td align="right" style="padding:8px 0;border-bottom:1px solid ${REGLA};font-size:14px;color:${TINTA}">${dinero(l.precio * l.unidades, c.moneda)}</td></tr>`).join('');

  const cupon = c.cupon ? `<div style="border:1px dashed ${COLOR};border-radius:10px;padding:14px;text-align:center;margin:20px 0">
<div style="font-size:12px;color:${SUAVE};letter-spacing:.06em;text-transform:uppercase">Código de descuento</div>
<div style="font-family:Georgia,'Times New Roman',serif;font-size:24px;color:${COLOR};padding-top:4px">${esc(c.cupon)}</div></div>` : '';

  const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="560" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:21px;color:${COLOR};padding-bottom:4px">${esc(d.tienda)}</div>
<div style="font-family:Georgia,'Times New Roman',serif;font-size:24px;color:${TINTA};padding:8px 0 4px">${esc(SALUDO[Math.min(c.paso, 3)](c.nombre))}</div>
<p style="font-size:15px;color:${TINTA};line-height:1.5;margin:8px 0 20px">${CUERPO[Math.min(c.paso, 3)]}</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse">${lineas}
<tr><td style="padding:12px 0;font-size:15px"><b>Total</b></td><td align="right" style="padding:12px 0;font-size:15px"><b>${dinero(c.total, c.moneda)}</b></td></tr></table>
${cupon}
<table cellspacing="0" style="margin:20px 0"><tr><td style="background:${COLOR};border-radius:8px">
<a href="${esc(c.url_recuperacion)}" style="display:inline-block;padding:13px 26px;color:#fff;text-decoration:none;font-size:15px">${esc(d.marca_texto_boton)}</a>
</td></tr></table>
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE};line-height:1.5">
${esc(d.tienda)} · <a href="${esc(d.web)}" style="color:${SUAVE}">${esc(d.web.replace(/^https?:\/\//, ''))}</a><br>
Recibes este aviso porque dejaste un carrito en nuestra tienda y aceptaste recibir comunicaciones.
Para dejar de recibirlos, escribe a <a href="mailto:${esc(d.email_bajas)}" style="color:${SUAVE}">${esc(d.email_bajas)}</a>.
</div>
</td></tr></table></td></tr></table></body></html>`;

  // En modo demo los compradores son inventados: el aviso te llega a ti, con el destinatario en el asunto.
  const demo = d.fuente === 'demo' && d.email_to;
  return { json: {
    ...c,
    email_to: demo ? d.email_to : c.email,
    email_from: d.email_from,
    asunto: demo ? `[Demo → ${c.email}] ${c.asunto}` : c.asunto,
    email_html,
  } };
});

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Apunta qué avisos salieron de verdad. Solo lo que se envió se marca como enviado:
// si el SMTP falla, ese carrito volverá a intentarlo en la siguiente pasada.
const cfg = $('Configuración').first().json;
const previstos = $('Preparar avisos').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json || {});
const estado = __estadoCliente();
estado.carritos = estado.carritos || {};
estado.historico = estado.historico || { enviados: 0, recuperados: 0, valor_recuperado: 0 };

const enviados = [];
const fallidos = [];
previstos.forEach((p, i) => {
  const r = respuestas[i] || {};
  const error = r.error || r.errorMessage;
  if (error) {
    fallidos.push({ id: p.id, email: p.email, paso: p.paso,
      error: String(typeof error === 'object' ? error.message || JSON.stringify(error) : error).slice(0, 200) });
    return;
  }
  const previo = estado.carritos[p.id] || { pasos: [] };
  const pasos = [...new Set([...previo.pasos, ...(p.saltados || []), p.paso])].sort((a, b) => a - b);
  estado.carritos[p.id] = { pasos, ultimo_envio: cfg.ahora, total: p.total, email: p.email };
  estado.historico.enviados += 1;
  enviados.push({ id: p.id, email: p.email, paso: p.paso, total: p.total });
});

return [{ json: { hubo_envios: true, enviados, fallidos, historico: { ...estado.historico } } }];

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Rama en la que no había a quién escribir.
const estado = __estadoCliente();
return [{ json: { hubo_envios: false, enviados: [], fallidos: [],
  historico: estado.historico || { enviados: 0, recuperados: 0, valor_recuperado: 0 } } }];

// Resumen para el dueño de la tienda: qué se ha enviado, qué se ha recuperado y qué no se tocó.
const d = $('Decidir a quién escribo').first().json;
const ej = $input.first().json || { hubo_envios: false, enviados: [], fallidos: [], historico: {} };
const r = d.resumen;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24'; const OK = '#2c5f3c';
const dinero = (n) => `${Number(n || 0).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;
const h3 = (t) => `<h3 style="font-family:Georgia,'Times New Roman',serif;font-size:17px;color:${VERDE};margin:24px 0 8px;font-weight:normal">${t}</h3>`;
const th = (t, der) => `<th align="${der ? 'right' : 'left'}" style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${REGLA};padding:6px 0;font-weight:normal">${t}</th>`;
const td = (t, der) => `<td align="${der ? 'right' : 'left'}" style="font-size:13px;color:${TINTA};border-bottom:1px solid ${REGLA};padding:8px 0">${t}</td>`;
const cifra = (n, t, color) => `<td width="25%" style="padding:0 8px"><div style="font-family:Georgia,serif;font-size:30px;color:${color || VERDE};line-height:1">${n}</div><div style="font-size:12px;color:${SUAVE};padding-top:2px">${t}</div></td>`;

const filas = ej.enviados.slice(0, 12).map((e) => `<tr>${td(esc(e.email))}${td(`aviso ${e.paso}`)}${td(dinero(e.total), 1)}</tr>`).join('');
const filasRec = d.recuperados.slice(0, 10).map((x) => `<tr>${td(esc(x.email))}${td(`tras ${x.pasos} aviso${x.pasos > 1 ? 's' : ''}`)}${td(dinero(x.total), 1)}</tr>`).join('');
const om = d.omitidos;
const motivos = [
  om.sin_consentimiento ? `${om.sin_consentimiento} sin consentimiento` : '',
  om.sin_email ? `${om.sin_email} sin email` : '',
  om.importe_bajo ? `${om.importe_bajo} por debajo de ${dinero(d.minimo_total)}` : '',
  om.caducados ? `${om.caducados} caducados` : '',
  om.al_dia ? `${om.al_dia} ya al día` : '',
].filter(Boolean);

const cuerpo = `<table width="100%" cellspacing="0" style="margin:4px 0 8px"><tr>
${cifra(ej.enviados.length, 'avisos enviados')}${cifra(dinero(r.valor_en_juego), 'en juego')}${cifra(d.recuperados.length, 'recuperados', d.recuperados.length ? OK : null)}${cifra(dinero(r.valor_recuperado), 'recuperado', d.recuperados.length ? OK : null)}
</tr></table>
${ej.enviados.length ? `${h3('Avisos enviados')}
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Comprador')}${th('Paso')}${th('Carrito', 1)}</tr>${filas}</table>
${ej.enviados.length > 12 ? `<p style="font-size:12px;color:${SUAVE};margin:8px 0 0">…y ${ej.enviados.length - 12} más.</p>` : ''}`
  : `<p style="font-size:15px;color:${TINTA};margin:0">Ningún carrito necesitaba un aviso en esta pasada.</p>`}
${d.recuperados.length ? `${h3('Carritos recuperados')}
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Comprador')}${th('Cuándo')}${th('Pedido', 1)}</tr>${filasRec}</table>` : ''}
${ej.fallidos.length ? `<p style="font-size:13px;color:${ALERTA};margin-top:16px">${ej.fallidos.length} aviso(s) no salieron (se reintentan en la próxima pasada): ${esc(ej.fallidos.slice(0, 3).map((f) => f.email).join(', '))}</p>` : ''}
${d.en_espera ? `<p style="font-size:13px;color:${SUAVE};margin-top:12px">${d.en_espera} carrito(s) esperan a la próxima pasada por el tope de ${d.max_envios_por_ejecucion} envíos.</p>` : ''}
${motivos.length ? `<p style="font-size:13px;color:${SUAVE};margin-top:12px">No se escribió a: ${motivos.join(' · ')}.</p>` : ''}
<p style="font-size:13px;color:${SUAVE};margin-top:20px">Desde que está en marcha: ${ej.historico.enviados || 0} avisos, ${ej.historico.recuperados || 0} carritos recuperados y ${dinero(ej.historico.valor_recuperado)} en pedidos.</p>`;

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="680" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${VERDE}">Carritos abandonados · ${esc(d.tienda)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 12px;border-bottom:1px solid ${REGLA}">${new Date(d.ahora).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })} · ${r.carritos_vistos} carritos revisados</div>
${cuerpo}
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const telegram = `🛒 <b>Carritos · ${d.tienda}</b>\n` +
  `<b>Avisos enviados:</b> ${ej.enviados.length} (${dinero(r.valor_en_juego)} en juego)\n` +
  (d.recuperados.length ? `<b>Recuperados:</b> ${d.recuperados.length} · ${dinero(r.valor_recuperado)}\n` : '') +
  (ej.fallidos.length ? `⚠️ ${ej.fallidos.length} no salieron\n` : '') +
  `<i>Total desde el inicio: ${ej.historico.recuperados || 0} recuperados, ${dinero(ej.historico.valor_recuperado)}</i>`;

// Sin avisos, recuperados ni fallos no hay nada que contar: no se manda nada (corre cada 30 minutos).
const hayAlgo = Boolean(ej.enviados.length || d.recuperados.length || ej.fallidos.length);
return [{ json: { ...d, enviar_email: Boolean(d.enviar_email && hayAlgo), enviar_telegram: Boolean(d.enviar_telegram && hayAlgo), hay_algo: hayAlgo, asunto: `Denoro · Carritos de ${d.tienda}: ${ej.enviados.length} avisos${d.recuperados.length ? `, ${d.recuperados.length} recuperados` : ''}`, email_html, telegram, ejecucion: ej } }];

// (Se añade a cada automatización en su versión «para un cliente»)
// Guarda en denoro_estado lo que ha pasado en esta ejecución, para enseñarlo en el panel.
const d = $input.first()?.json || {};
const cfg = $('Configuración').first().json;
const txt = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const titulo = txt(d.asunto).replace(/^[^\p{L}\p{N}]*Denoro · /u, '').replace(/^[^\p{L}\p{N}]+/u, '');
return [{ json: {
  clave: cfg.__clave, token: cfg.__token, snapshot: '',
  resumen: JSON.stringify({
    ultima: new Date().toISOString(), ok: true, modo: cfg.modo || null,
    titulo: (titulo || "Ningún carrito necesitaba aviso").slice(0, 200),
    texto: txt(d.telegram).slice(0, 1500),
    avisado: Boolean(d.asunto && (d.enviar_email || d.enviar_telegram)),
    demo: [cfg.fuente, cfg.destino].includes('demo'),
  }),
} }];
